SELECT 
FROM exam_session_section t
WHERE t.session_id = #{sessionId}
  AND t.section_no = #{sectionNo}
LIMIT 1

mapper.update:
UPDATE exam_session_section
SET status = 'IN_PROGRESS',
    started_at = #{startedAt}
WHERE id = #{id}
  AND status = 'PENDING'

UPDATE exam_session_section
SET status = #{status},
    used_sec = #{usedSec},
    finished_at = #{finishedAt}
WHERE id = #{id}

UPDATE exam_session_section
SET objective_score = #{objectiveScore}
WHERE id = #{id}

UPDATE exam_session_section
SET used_sec = #{usedSec}
WHERE id = #{id}
